/**
 * Bundle the Video.js player into one ES module and write it as a string
 * export. A preview frame is an opaque origin that cannot fetch plugin files,
 * so the app inlines this source into each frame document that has a player.
 */
import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = (path: string) => fileURLToPath(new URL(path, import.meta.url));
const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");
const manifest = JSON.parse(
  await readFile(videojsManifestPath(), "utf8"),
) as { version: string };
const entry = await readFile(here("./video-player-entry.ts"), "utf8");
const result = await Bun.build({
  entrypoints: [here("./video-player-entry.ts")],
  format: "esm",
  target: "browser",
  minify: true,
});
if (!result.success) throw new AggregateError(result.logs, "Video.js bundle failed");
const source = await result.outputs[0]!.text();
await writeFile(
  here("./video-player.ts"),
  `// Generated by \`bun run vendor:player\` from @videojs/html ${manifest.version}. Do not edit.\n` +
    `export const VIDEO_PLAYER_VERSION = ${JSON.stringify(manifest.version)};\n` +
    `export const VIDEO_PLAYER_ENTRY_HASH = ${JSON.stringify(sha256(entry))};\n` +
    `export const VIDEO_PLAYER_ETAG = ${JSON.stringify(`"${sha256(source).slice(0, 32)}"`)};\n` +
    `export default ${JSON.stringify(source)};\n`,
);
console.log(`Wrote vendor/video-player.ts (${source.length} bytes, @videojs/html ${manifest.version})`);

/** `@videojs/html` exports no package.json, so walk up from its entry. */
function videojsManifestPath(): string {
  let directory = dirname(createRequire(import.meta.url).resolve("@videojs/html"));
  while (!directory.endsWith(join("node_modules", "@videojs", "html"))) directory = dirname(directory);
  return join(directory, "package.json");
}
